learn=[('Design tools by risk', 'Read the fictional ticket and customer history, then tag category and priority automatically. A customer-facing reply is a different action and needs an explicit reviewer decision.'), ('Build four in-process MCP tools', 'Use tool(), Zod schemas and createSdkMcpServer for get_ticket, get_customer_history, set_priority and send_reply. The teaching helpdesk is a local JSON fixture, with no email provider.'), ('Pause at the native permission boundary', 'Leave send_reply out of allowedTools. The real canUseTool callback waits on a browser approval promise while the draft remains unrecorded.'), ('Approve, edit or reject', 'Approve the original draft, edit its body through updatedInput, or reject the native call. The UI cannot retarget a reply to another ticket. Each exact approved ticket/body grant can be consumed once.'), ('Handle errors and limits', 'Return isError for missing tickets and a deliberately unavailable history fixture. Preserve a native one-turn failure and validate a real typed triage result.'), ('Audit and batch safely', 'PostToolUse records actual tool results. Inspect local JSON and approval decisions together. Batch starts one fresh query per ticket and requires a separate review for each reply.')]
labels=[('approve', 'Approve original draft'), ('edit', 'Edit and approve exact replacement'), ('reject', 'Reject - no reply recorded'), ('missing', 'Missing ticket - tool error'), ('historyerror', 'History fixture error - acknowledge gap'), ('structured', 'Typed triage summary and approval'), ('batch', 'Two tickets - two fresh queries'), ('turnlimit', 'One turn - native limit result'), ('audit', 'PostToolUse audit and local state')]
runsteps=[('Prerequisites', 'Use Node.js 24+, API credit and a supported model. Windows may require Git Bash. The lesson uses fictional local helpdesk data: no real support account, email service, GitHub token or Managed Agents IDs are required.', 'node --version\nnpm --version'), ('Install and create .env', 'Preserve an existing .env. Enter your own API key privately; inherited shell variables take precedence. The npm scripts load the file when Node starts. Never publish the real .env.', 'cd .\\agent-sdk\\lesson53-support-triage\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env'), ('Start and navigate', 'Keep the terminal open, open the five student pages and choose an experiment. Reuse an existing instance or change PORT and restart if a different process occupies the port.', 'npm start\n# http://127.0.0.1:3153'), ('Review a real pending draft', 'Choose Approve, Edit or Reject and click Run. The real SDK reads the ticket and history, then tags it. When paused, inspect the draft and recorded-replies-before count. Click Approve, change the text and click Edit and approve, or click Reject. The mode name does not automatically approve anything.', 'npm run sample:env -- approve\n# Terminal sample also asks a/e/r before recording a reply.'), ('Compare errors and structured data', 'Missing reads T-404 and must stop without mutation. History error is a controlled local fixture failure; the draft must not invent history. Structured requests a schema-validated summary after the actual approval outcome.', 'npm run sample:env -- missing\nnpm run sample:env -- historyerror\nnpm run sample:env -- structured'), ('Inspect batch, limits and audit', 'Batch runs two fresh queries and needs two explicit decisions. Turn limit preserves a native error_max_turns. Audit displays actual PostToolUse responses. Each run retains helpdesk.json and audit.json under the ignored .runtime/runs/<run-id> folder. Read this local record; it is not proof of real email delivery.', 'npm run sample:env -- batch\nnpm run sample:env -- turnlimit\nnpm run sample:env -- audit\nnpm test')]
specs=[('Validate the experiment', 'src/protocol.ts', 'if (', 'Accept only a fixed lesson mode. Browser configuration cannot supply arbitrary paths, endpoints, tool definitions or approval decisions.', 0, 1, 9), ('Copy fictional helpdesk data', 'src/helpdesk.ts', 'const file = new URL', 'Each run copies a tracked fictional seed into its own ignored runtime JSON. No external helpdesk or real customer is contacted.', 1, 3, 7), ('Define the read tool and error response', 'src/helpdesk.ts', 'const getTicket = tool(', 'tool() declares a bounded ticket ID and read-only annotation. The shared wrapper returns isError for controlled tool failures, preserving an actual MCP result.', 1, 2, 9), ('Separate safe tools from the sender', 'src/helpdesk.ts', 'export const SAFE_TOOLS', 'Only the two reads and local tagging tool are automatically allowed. send_reply is deliberately absent so native permissions can ask the reviewer.', 1, 2, 5), ('Start the real query with bounded options', 'src/agent.ts', 'const run = query(', 'Use a real SDK query, default permission mode, isolated settings, finite turns and an estimate threshold. No built-in tool or wildcard sender permission is exposed.', 1, 2, 8), ('Wait on the native reply permission', 'src/agent.ts', 'const details = {', 'canUseTool receives the actual ticket, draft and native tool-use ID. It waits on a pending browser approval request; reads and tagging did not wait for this callback.', 2, 1, 11), ('Register the one-use approval request', 'src/approvals.ts', 'pending.set(id, settle);', 'Register before emitting the SSE request so a fast reviewer response is not lost. Abort or timeout rejects and removes the waiter. This local teaching UI has no production reviewer authentication.', 1, 0, 10), ('Validate and resolve the browser decision', 'src/server.ts', 'const { id, decision }', 'The bounded same-origin JSON route accepts only an existing approval ID and a valid decision. A stale or replayed ID returns 409. Reviewers cannot change the ticket ID.', 0, 1, 8), ('Apply the reviewer edit through updatedInput', 'src/agent.ts', 'if (validated.action === "reject")', 'Reject returns the SDK native deny response. Approve or edit grants one exact ticket/body pair and returns updatedInput for that same ticket.', 1, 2, 12), ('Record only the exact approved reply', 'src/helpdesk.ts', 'if (!ledger.consume', 'The handler independently consumes a one-use grant. A changed body or unapproved call is refused. It records only local JSON and explicitly reports that no real message was sent.', 2, 3, 12), ('Observe actual post-tool results', 'src/agent.ts', 'PostToolUse: [', 'The native PostToolUse hook records actual tool input and response. Audit records complement the local JSON and reviewer decision; a successful tag is not a sent reply.', 2, 1, 12), ('Preserve results and validate typed triage', 'src/agent.ts', 'Triage.parse(results.at(-1)?.structuredOutput);', 'Validate the actual structured output with Zod. A missing field or invalid summary stays a validation error. Batch preserves separate native query results and sessions.', 2, 1, 4), ('Check approvals against persisted replies', 'src/agent.ts', 'const repliesMatchApprovals', 'Every recorded reply must exactly match an approve/edit decision for its ticket. Retain helpdesk.json and audit.json, then remove only the disposable SDK workspace.', 3, 0, 10)]
reference=[('Fictional helpdesk boundary', 'Four genuine in-process MCP tools read and mutate local classroom JSON. send_reply records a local fixture entry; there is no real email transport or external helpdesk API. A production adapter would need separate authentication, idempotency, delivery tracking and authenticated reviewers.'), ('Permission ordering', 'Bare allowedTools entries may bypass canUseTool. The sender is excluded; default permission mode falls through to the callback. The tool handler also consumes an exact one-use ticket/body grant so an unintended permission bypass cannot record an unapproved reply.'), ('Edited input', 'The decision route accepts body edits but no ticketId. canUseTool returns the original ticket ID and reviewed body in updatedInput. The handler verifies that exact pair and refuses a second reply for a ticket in the same run.'), ('Rejection and expiry', 'Reject uses native deny. The prompt forbids retries or alternate delivery routes. Pending requests expire after two minutes or abort with the run, and stale/replayed decisions return 409. Retry policies and stronger durable idempotency would be needed for a production service.'), ('Errors are explicit', 'Missing ticket is a genuine MCP isError response for fictional T-404. Historyerror deliberately fails the local history fixture, not a real provider. The agent should explain the gap rather than invent previous contacts.'), ('Automatic local tagging', 'set_priority mutates only the run JSON and is explicitly automatically allowed for this exercise. It is not annotated read-only. Production tagging policies may need additional review.'), ('Limits and typed output', 'Normal queries allow twelve turns and a $0.35 SDK estimate threshold; estimates can overshoot before being checked. Turnlimit allows one turn and preserves the native error. Structured uses the actual SDK JSON schema output followed by Zod validation.'), ('Batch and audit', 'Batch makes one fresh SDK query per ticket, sequentially, while sharing this run local JSON. Each sender call requests an independent decision. PostToolUse captures actual responses; approval decisions retain the original and approved body.'), ('Credentials and privacy', 'Keep the API key only in the private .env or shell. SDK state is disposable; runtime JSON and audits stay local and are excluded from Git. This is a fictional classroom fixture, not comprehensive production DLP or a secure multi-user deployment.'), ('Primary references', 'https://code.claude.com/docs/en/agent-sdk/custom-tools ; https://code.claude.com/docs/en/agent-sdk/user-input ; https://code.claude.com/docs/en/agent-sdk/hooks ; https://code.claude.com/docs/en/agent-sdk/structured-outputs')]
body='<div class="flow"><div><b>01 · Configure</b><p>Select a triage experiment</p></div><span>→</span><div><b>02 · Observe</b><p>Run the real SDK</p></div><span>→</span><div><b>03 · Verify</b><p>Review the reply and local state</p></div></div><section class="panel" id="controls"><h2>Read, triage and review the reply</h2><p id="configuration" class="meta">Checking local server…</p><label for="mode">Triage experiment</label><select id="mode"><option value="approve">Approve original draft</option><option value="edit">Edit and approve exact replacement</option><option value="reject">Reject - no reply recorded</option><option value="missing">Missing ticket - tool error</option><option value="historyerror">History fixture error - acknowledge gap</option><option value="structured">Typed triage summary and approval</option><option value="batch">Two tickets - two fresh queries</option><option value="turnlimit">One turn - native limit result</option><option value="audit">PostToolUse audit and local state</option></select><button class="primary" id="run" disabled>Run support triage →</button><p>Four real in-process MCP tools use fictional local JSON. Reads and tagging run automatically. send_reply pauses for your explicit decision; no real customer or email service is contacted. Normal queries allow 12 turns and a $0.35 SDK estimate threshold.</p></section><section class="step" id="specialists-panel"><h2>Actual triage evidence</h2><div class="grid"><article class="card"><h3>Tickets tagged</h3><p class="metric" id="span-count">0</p></article><article class="card"><h3>Review decisions</h3><p class="metric" id="metric-count">0</p></article><article class="card"><h3>Local replies recorded</h3><p class="metric" id="log-count">0</p></article></div><p>Counts come from actual tool handlers, reviewer decisions and local persisted replies. A recorded reply is a fictional local entry, not real email delivery.</p></section><div class="workspace"><section class="panel" id="chat-panel"><h2 id="status" aria-live="polite">Ready</h2><div id="conversation"></div></section><section class="panel" id="option-panel"><h2>Actual permission and tool configuration</h2><pre class="json-view"><code id="options" class="language-json">{}</code></pre></section></div><section class="step" id="trace-panel"><h2>Actual helpdesk tool handlers</h2><p>Each row comes from a real in-process MCP handler. An isError result remains a failed tool call.</p><div class="table"><table><thead><tr><th>Tool</th><th>Input</th><th>Succeeded</th><th>Actual output</th></tr></thead><tbody id="trace-history"></tbody></table></div></section><section class="step" id="metric-panel"><h2>Reviewer decisions</h2><p>Compare the original draft and actual approved body. Reject has no approved body and must record no reply.</p><div class="table"><table><thead><tr><th>Ticket</th><th>Action</th><th>Original draft</th><th>Approved body or rejection</th></tr></thead><tbody id="metric-history"></tbody></table></div></section><section class="step" id="model-panel"><h2>PostToolUse audit</h2><label for="user-filter">Filter by exact MCP tool name</label><input id="user-filter" placeholder="mcp__helpdesk__send_reply"><p>Leave blank for all tools, or enter the exact full MCP name.</p><div class="table"><table><thead><tr><th>Tool</th><th>Actual input</th><th>Actual response</th></tr></thead><tbody id="log-history"></tbody></table></div></section><section class="step" id="results-panel"><h2>Native SDK result</h2><pre class="json-view"><code class="language-json" id="native-result">{}</code></pre></section><section class="step" id="catalog-panel"><h2>Native SDK tool requests</h2><pre class="json-view"><code class="language-json" id="requests">{}</code></pre></section><section class="step" id="storage-panel"><h2>Persisted tickets, replies and approval checks</h2><pre class="json-view"><code class="language-json" id="storage">{}</code></pre></section><section class="step" id="diagnostic-panel"><h2>Native results and validation errors</h2><pre class="json-view"><code class="language-json" id="diagnostics">{}</code></pre></section><section class="step" id="observation-panel"><h2>Actual SDK observations - sanitized</h2><pre class="json-view"><code class="language-json" id="telemetry">{}</code></pre></section><section class="step" id="evidence-panel"><h2>Independent actual run evidence</h2><pre class="json-view"><code class="language-json" id="evidence">{}</code></pre><button id="download">Download actual observations</button></section>'
env='ANTHROPIC_API_KEY=your_api_key\nCLAUDE_MODEL=claude-sonnet-4-6\nPORT=3153\n# Windows only, if required:\n# CLAUDE_CODE_GIT_BASH_PATH=C:/Program Files/Git/bin/bash.exe\n'

body=body.replace('<section class="step" id="specialists-panel">','<section class="step" id="approval-panel" hidden><h2 id="approval-title">Review the pending reply</h2><p id="approval-meta" class="meta"></p><div id="approval-body" class="note"></div><label for="edited-body">Reviewed replacement body</label><textarea id="edited-body" maxlength="1600"></textarea><div class="actions"><button id="approve" class="primary">Approve original</button><button id="edit">Edit and approve</button><button id="reject">Reject</button></div><p id="approval-feedback" aria-live="polite"></p></section>'+'<section class="step" id="specialists-panel">')
document('/','Automate triage. <em>Review every reply.</em>','Read fictional tickets, tag priorities and approve, edit or reject the actual agent draft.',body,'<script type="module" src="/client.js"></script>')
document('/learn.html','What you <em>will learn.</em>','Build real MCP tools, gate reply actions and inspect actual local evidence.',cards(learn))
body=''
for i,(title,explanation,code) in enumerate(runsteps,1):body+=f'<section class="step" id="run-step-{i}"><span class="number">{i:02}</span><h2>{title}</h2><p>{explanation}</p>'+snippet(code,'powershell')+'</section>'
body+='<section class="step"><h2>Your private .env</h2>'+snippet(env,'dotenv')+'<p>Keep the key private, restart after edits, and preserve an existing file. Existing shell values take precedence. If the port is occupied, change PORT.</p></section>'
document('/run.html','Configure and <em>run the app.</em>','Install, configure privately and inspect the nine experiments.',body)
steps=[];arrows=[];lanes=['Reviewer UI','TypeScript host','Agent SDK / MCP','Local helpdesk JSON','Evidence / host']
for n,(title,source,anchor,explanation,a,b,count) in enumerate(specs,1):
 text=(APP/source).read_text(encoding='utf-8');lines=text.splitlines();idx=next(i for i,l in enumerate(lines) if anchor in l)
 code='\n'.join(lines[idx:idx+count]).strip()
 steps.append(dict(number=n,title=title,source=source,code=code,language='javascript' if source.endswith('.js') else 'typescript',explanation=explanation,firstLine=idx+1,lastLine=idx+count,anchors=[lines[idx].strip()],sourceSHA256=hashlib.sha256(text.encode()).hexdigest(),narration=f'Step {n}. {explanation} This source excerpt shows the corresponding application statement.'))
 arrows.append([a,b,f'{n}. {title}'])
(APP/'scripts/architecture-data.json').write_text(json.dumps(dict(lanes=lanes,arrows=arrows,steps=steps),indent=2),encoding='utf-8')
xs=[170,520,870,1220,1570];svg=['<svg xmlns="http://www.w3.org/2000/svg" width="1740" height="1600" viewBox="0 0 1740 1600"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto"><path d="M0 0 L10 5 L0 10z" fill="#087fff"/></marker></defs><rect width="1740" height="1600" fill="#f4f9ff"/><text x="40" y="52" font-family="Arial" font-size="34" fill="#101a44">Lesson 53 · Read → triage → review → record</text>']
for x,label,colour in zip(xs,lanes,['#087fff','#8838ff','#00a977','#8838ff','#ee5425']):svg.append(f'<rect x="{x-150}" y="90" width="300" height="80" rx="16" fill="{colour}"/><text x="{x}" y="139" text-anchor="middle" font-family="Arial" font-size="27" fill="white">{escape(label)}</text><path d="M{x} 170 V1550" stroke="#aec6df" stroke-dasharray="8 7"/>')
for i,(a,b,label) in enumerate(arrows):
 x1,x2=xs[a],xs[b];y=245+i*98;path=f'M{x1} {y} h65 v24 h-65' if a==b else f'M{x1} {y} H{x2}';svg.append(f'<text x="{max(40,min(min(x1,x2)+10,1700-len(label)*13))}" y="{y-18}" fill="#142d53" font-family="Arial" font-size="24">{escape(label)}</text><path d="{path}" stroke="#087fff" stroke-width="3" marker-end="url(#arrow)"/>')
(PUBLIC/'architecture.svg').write_text(''.join(svg)+'</svg>',encoding='utf-8')
walk=''
for s in steps:walk+=f'<section class="step workflow-step" id="workflow-step-{s["number"]:02}"><span class="number">{s["number"]:02}</span><h3>{s["number"]}. {s["title"]}</h3><p>{escape(s["explanation"])}</p><p class="source">Source: {s["source"]} · lines {s["firstLine"]}–{s["lastLine"]} · selected source; surrounding code omitted</p>'+snippet(s['code'],s['language'])+'</section>'
document('/architecture.html','Architecture and <em>UML workflow.</em>','Every workflow step includes its corresponding coloured code excerpt.','<p class="note">The real SDK calls four in-process MCP tools. Reads and local tagging are automatically allowed. send_reply waits on the native permission callback and the reviewer UI. An exact one-use approval guards the local JSON write. Numbered steps group related paths; no external helpdesk or email service is connected.</p><a class="button" href="/architecture.svg" download>Download UML SVG</a><div class="diagram"><img src="/architecture.svg" alt="Thirteen source-linked support triage workflow steps"></div>'+walk)

document('/walkthrough.html','How the app <em>was built.</em>','Every architecture step has matching coloured TypeScript.',cards(reference)+walk)

readme='# Claude Agent SDK · Lesson 53 · Build a support triage agent\n\nFive student pages, a real SDK lab with a fictional JSON helpdesk and thirteen source-linked UML code steps.\n\n## What you will learn\n\n'+''.join(f'- {a}: {b}\n' for a,b in learn)
readme+='\n## Configure and run\n\n```powershell\ngit clone https://github.com/luiscoco/Udemy-Claude-Agent-SDK-lesson53-app.git\ncd .\\Udemy-Claude-Agent-SDK-lesson53-app\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env\nnpm start\n```\n\nFrom presentations: `cd .\\agent-sdk\\lesson53-support-triage`. Open http://127.0.0.1:3153. Node 24+, API credit and Windows Git Bash if needed.\n\n## Create your .env file\n\nCopy the template once and enter your own model key privately. Restart after edits. Existing shell values take precedence.\n\n```dotenv\n'+env+'```\n\nNo real helpdesk credentials, email transport, GitHub token or Managed Agents IDs are required. The SDK key remains private.\n\n## Run the experiments\n\n'
for title,explanation,code in runsteps[3:]:readme+=f'### {title}\n\n{explanation}\n\n```powershell\n{code}\n```\n\n'
readme+='## How the app was built\n\n'
for s in steps:readme+=f'### {s["number"]}. {s["title"]}\n\n{s["explanation"]}\n\nSource: `{s["source"]}`, selected lines {s["firstLine"]}–{s["lastLine"]}. Surrounding code omitted.\n\n```typescript\n{s["code"]}\n```\n\n'
readme+='## Reference topics and limits\n\n'+''.join(f'- {a}: {b}\n' for a,b in reference)+'\n## Validation\n\nRun `npm test` and `npm run build:client`. Regenerate pages with `python scripts/build-pages.py`. Secrets, dependencies, recordings and teaching media are excluded from Git.\n'
(APP/'README.md').write_text(readme,encoding='utf-8')
(PUBLIC/'style.css').write_text((PUBLIC/'style.css').read_text(encoding='utf-8')+'\n.metric{font-size:34px;font-weight:800}.json-view{max-height:380px}.table{max-height:420px;overflow:auto}td{min-width:140px;max-width:500px;overflow-wrap:anywhere}.markdown-body{font-size:22px;line-height:1.65}#conversation{max-height:450px;overflow:auto}input{width:100%;font:inherit;padding:16px;border:1px solid var(--line);border-radius:14px;color:var(--ink);background:var(--paper)}\n',encoding='utf-8')
print('Built five Lesson 53 pages with 13 coloured workflow snippets.')
